// Las doce inscripciones (anexo 7.1), con el texto del Excel; certeza: s, d, n.
export const INSCRIPCIONES_MIN = [{"id": "968A", "date": "finales del s. VI a.C.", "text": "α̣ἴτε ἄλλα[ι] <--\nἀλοιφᾶι (h)ορο͂ <--\nβέλτερον <--", "dialecto": "Acayo", "certeza": "d"}, {"id": "2821A", "date": "mediados del s. V a.C.", "text": "[- - - πὸτ τὸν δεῖνα συνθ]έμενος : ἒ̅ ποτ' ἄλ-\n[λον]", "dialecto": "Acayo", "certeza": "d"}, {"id": "2822A", "date": "segunda mitad del s. V a.C.", "text": "περὶ το͂ν Ι[- - -] \nτὰν Μελίζ[ουσαν - - -]- \nια εἴε̅", "dialecto": "Acayo", "certeza": "d"}, {"id": "2824B", "date": "mediados del s. V a.C.", "text": "[περὶ] εὐπρα[γ]ίας καὶ \n[ὑγιεί]ας αὐτο͂ καὶ γέ-\nν(ε)ος ποτ[ευχό]μ̣ενο[ς]", "dialecto": "Acayo", "certeza": "d"}, {"id": "4144A", "date": "primera mitad del s. V a.C.", "text": "[- - -]Ι[. . .]Σ : θε:ο̣ῖς : Ο[- - -] \n[- - -] τὰ[ν] θ̣έ̣ρμαν : καὶ [- - -]\n[- - -] ἐξ̣(ι)δρό̅σας", "dialecto": "Acayo", "certeza": "d"}, {"id": "109A", "date": "s. V a.C.", "text": "θεός• αἰ Ἀθ[- - -] \nἢ ἐπευχόμε[νος - - -]\nπαῦσαι τὸ ν[εῖκος - - -]\nκαλὰ • ἢ 'πὶ πάν[τα - - -]", "dialecto": "Acayo", "certeza": "n"}, {"id": "4145B", "date": "primera mitad del s. V a.C.", "text": "[θεό]ς· [Ἱ]πόζαμο(ς) ἐπισ̣[τορεῖται - - -]\n[- - -]Ε̣ΟΥΣΟ[. .]ΑΤΑ[. .][- - -] \n[- - - θύσας] ἒ̅ εὐξ̣άμενο[ς - - -] \n[- - -]ν ὅτι κά[λλι]στα Κ̣[.][- - -] \n[- - -]ΣΤΑΤΑ[. . . .]ΕΝΕ[. .][- - -] \n[- - -] ἱαρο͂τα[ι]", "dialecto": "Eleo", "certeza": "d"}, {"id": "LOD 29", "date": "ss. V-IV a.C.", "text": "῏Ε ἄλλαν μαστείε̅ι ;", "dialecto": "Eleo", "certeza": "d"}, {"id": "2493A", "date": "principios del s. IV a.C.", "text": "Ζεῦ καὶ Διώνα· ἦ ἔσσονται παῖ-\nδες ἐκ τᾶς γυναικὸς Κεβαλίωι \nτᾶς νῦν ἔχει κ[α]ὶ ζώσοντι;", "dialecto": "Macedonio", "certeza": "d"}, {"id": "94", "date": "primer cuarto del s. IV a.C.", "text": "Ἄλβειος περὶ παντυχίας", "dialecto": "Macedonio", "certeza": "n"}, {"id": "LOD 89Aa", "date": "s. IV a.C.", "text": "Τύχα ἀγαθά. Ἦ τυγχάνοιμί κα ἐμπορευόμενος \nὅπυς κα δοκῆι σύμφορον ἔμειν καὶ ἄγων τῆι (?) κα δοκῆι \nἅμα τᾶι τέχναι χρεύμενος.", "dialecto": "Rodio", "certeza": "d"}, {"id": "27A", "date": "principios del s. V a.C.", "text": "[- - -] αἰ συνναίεν ΤΑΑΡ[- - -]", "dialecto": "Textos no griegos", "certeza": "d"}];
